Not if the application has the right permissions on their installation manifest.<p>&lt;uses-permission android:name=&quot;android.permission.INTERNET&quot; &#x2F;&gt;<p>Then you need to write the server handling code on a background application thread, with perfectly working server sockets.<p>This only works on wlan, or local network when using bluethooth, but who wants data modem for a server anyway.<p>With Gemini&#x27;s compliment,<p><pre><code>    import kotlinx.coroutines.Dispatchers
    import kotlinx.coroutines.withContext
    import java.io.BufferedReader
    import java.io.InputStreamReader
    import java.net.ServerSocket
    import java.net.Socket
    import java.net.SocketException

    class AndroidTcpServer {

        private var serverSocket: ServerSocket? = null
        private var isRunning = false

        &#x2F;&#x2F; Call this function from a CoroutineScope (e.g., lifecycleScope.launch)
        async suspend fun startServer(port: Int = 8080) {
            withContext(Dispatchers.IO) {
                try {
                    serverSocket = ServerSocket(port)
                    isRunning = true

                    &#x2F;&#x2F; Loop to continuously accept incoming client connections
                    while (isRunning) {
                        val clientSocket = serverSocket?.accept() &#x2F;&#x2F; Blocks until a client connects

                        if (clientSocket != null) {
                            &#x2F;&#x2F; Handle each client connection in a separate background routine
                            handleClient(clientSocket)
                        }
                    }
                } catch (e: SocketException) {
                    &#x2F;&#x2F; Triggered when stopServer() closes the socket
                    println(&quot;Server socket closed: ${e.message}&quot;)
                } catch (e: Exception) {
                    e.printStackTrace()
                } finally {
                    stopServer()
                }
            }
        }

        private suspend fun handleClient(socket: Socket) {
            withContext(Dispatchers.IO) {
                try {
                    val reader = BufferedReader(InputStreamReader(socket.getInputStream()))
                    val outputStream = socket.getOutputStream()

                    &#x2F;&#x2F; Read incoming text from client
                    val incomingMessage = reader.readLine()
                    println(&quot;Received from client: $incomingMessage&quot;)

                    &#x2F;&#x2F; Send a simple response back to the client
                    val response = &quot;Hello from Android Server!\n&quot;
                    outputStream.write(response.toByteArray())
                    outputStream.flush()

                } catch (e: Exception) {
                    e.printStackTrace()
                } finally {
                    &#x2F;&#x2F; Always close individual client connections
                    socket.close()
                }
            }
        }

        fun stopServer() {
            isRunning = false
            try {
                serverSocket?.close()
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

</code></pre>
